:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eee;
  --muted: #aaa;
}
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 18px;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px 20px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  font-size: 28px;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--accent);
}
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  font-size: 18px;
  background: var(--bg);
  border: 3px solid var(--muted);
  color: var(--text);
  outline: none;
}
input[type="text"]:focus {
  border-color: var(--accent);
}
button {
  font-size: 18px;
  padding: 10px 18px;
  background: var(--accent);
  color: #fff;
  border: 3px solid var(--accent);
  cursor: pointer;
  font-weight: bold;
  text-transform: uppercase;
  transition: background 0.1s, transform 0.1s;
}
button:hover {
  background: #ff6b81;
  border-color: #ff6b81;
}
button:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}
button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}
.counts {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  font-size: 16px;
  color: var(--muted);
}
.counts span span {
  color: var(--accent);
  font-weight: bold;
}
.todo-list {
  list-style: none;
}
.todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 2px dashed var(--muted);
}
.todo-list li:last-child {
  border-bottom: none;
}
.todo-list input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
}
.todo-list .todo-text {
  flex: 1;
  font-size: 18px;
  word-break: break-word;
}
.todo-list li.done .todo-text {
  text-decoration: line-through;
  color: var(--muted);
}
.todo-list .delete-btn {
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
  padding: 4px 10px;
  font-size: 16px;
  cursor: pointer;
}
.todo-list .delete-btn:hover {
  background: var(--accent);
  color: #fff;
}
.todo-list .delete-btn:active {
  transform: translate(2px, 2px);
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px 12px; }
  h1 { font-size: 24px; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

(function() {
  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');
  const list = document.getElementById('todo-list');

  let nextId = 1;
  const tasks = [];

  function updateCounts() {
    totalEl.textContent = tasks.length;
    remainingEl.textContent = tasks.filter(t => !t.done).length;
  }

  function renderTask(task) {
    const li = document.createElement('li');
    li.dataset.id = task.id;
    if (task.done) li.classList.add('done');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', 'Toggle task ' + task.id);
    checkbox.addEventListener('change', function() {
      task.done = checkbox.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    const text = document.createElement('span');
    text.className = 'todo-text';
    text.id = 'todo-text-' + task.id;
    text.textContent = task.text;

    const del = document.createElement('button');
    del.type = 'button';
    del.className = 'delete-btn';
    del.id = 'todo-delete-' + task.id;
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete task ' + task.id);
    del.addEventListener('click', function() {
      const idx = tasks.indexOf(task);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(text);
    li.appendChild(del);
    list.appendChild(li);
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;
    const task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    renderTask(task);
    input.value = '';
    updateCounts();
    input.focus();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') addTask();
  });

  updateCounts();
})();
